//! Generated API assembly bootstrap for sdkwork-merchandise.
//! Regenerated by pnpm api:assembly:materialize.
//!
//! Multi-surface merges mount shared infrastructure routes once at the assembly layer
//! so `/healthz`, `/livez`, `/readyz`, and `/metrics` are not duplicated per surface.

use axum::Router;
use sdkwork_merchandise_service_host::MerchandiseServiceHost;
use sdkwork_web_bootstrap::{ApiAssemblyContribution, ReadinessCheck, WebModule};
use sdkwork_web_core::{DomainContextInjector, HttpRouteManifest};
use std::sync::Arc;

pub type ApiAssembly = ApiAssemblyContribution;

pub struct ApiAssemblyContext {
    pub host: Arc<MerchandiseServiceHost>,
    pub domain_context_injectors: Vec<Arc<dyn DomainContextInjector>>,
    pub readiness_check: Arc<dyn ReadinessCheck>,
}

pub async fn assemble_api_router(context: ApiAssemblyContext) -> Result<ApiAssembly, String> {
    let ApiAssemblyContext {
        host,
        domain_context_injectors,
        readiness_check,
    } = context;
    let mut router = Router::new();
    router = router.merge(sdkwork_routes_merchandise_backend_api::gateway_mount(host).await);
    let mut routes = Vec::new();
    routes.extend_from_slice(
        sdkwork_routes_merchandise_backend_api::gateway_route_manifest().routes(),
    );
    ApiAssemblyContribution::from_manifest(
        "sdkwork-merchandise",
        "SDKWork merchandise API",
        router,
        HttpRouteManifest::from_owned_routes(routes),
        domain_context_injectors,
        readiness_check,
    )
}

pub async fn assemble_backend_api_contribution(
    context: ApiAssemblyContext,
) -> Result<ApiAssembly, String> {
    let ApiAssemblyContext {
        host,
        domain_context_injectors,
        readiness_check,
    } = context;
    let mut router = Router::new();
    router = router.merge(sdkwork_routes_merchandise_backend_api::gateway_mount(host).await);
    let mut routes = Vec::new();
    routes.extend_from_slice(
        sdkwork_routes_merchandise_backend_api::gateway_route_manifest().routes(),
    );
    ApiAssemblyContribution::from_manifest(
        "sdkwork-merchandise",
        "SDKWork merchandise Backend API",
        router,
        HttpRouteManifest::from_owned_routes(routes),
        domain_context_injectors,
        readiness_check,
    )
}

/// Installs this application as a Web Module with caller-supplied assembly
/// context (API_ASSEMBLY_SPEC §4.1.1).
pub async fn web_module_with_context(context: ApiAssemblyContext) -> Result<WebModule, String> {
    Ok(WebModule::from_contribution(
        assemble_api_router(context).await?,
    ))
}
